L = TARGET_LOCALES


def _t(*vals):
    """Build a locale->translation dict from positional args matching TARGET_LOCALES order."""
    return dict(zip(L, vals))


def _k(val):
    """Keep the same value for all locales (command/setting names)."""
    return {l: val for l in L}


def load_salvaged(domain):
    json_path = os.path.join(os.path.dirname(__file__), 'salvaged_translations.json')
    if not os.path.exists(json_path):
        return {}
    with open(json_path, 'r', encoding='utf-8') as f:
        all_salvaged = json.load(f)
    if domain not in all_salvaged:
        return {}
    result = {}
    for key_str, locale_map in all_salvaged[domain].items():
        parts = key_str.split('|||', 1)
        ctx = parts[0] if parts[0] else None
        msgid = parts[1]
        result[(ctx, msgid)] = locale_map
    return result


